import{_ as a,a as t,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 96 The dead return","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 96 The dead return","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 95 A fantasy","link":"/life/english/new-concept/book-2/unit-04/lesson-095"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 95 A fantasy","link":"/life/english/new-concept/book-2/unit-04/lesson-095"},"next":false},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-096.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-096.md"}'),o={name:"life/english/new-concept/book-2/unit-04/lesson-096.md"};function i(l,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="第二册-实践与进步-·-lesson-96-the-dead-return" tabindex="-1">第二册：实践与进步 · Lesson 96 The dead return <a class="header-anchor" href="#第二册-实践与进步-·-lesson-96-the-dead-return" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 96 The dead return&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>介绍纪念祖先的节庆时，应把传统信念与可观察的仪式分开；练习报道被动与文化说明。本课的语言观察是：are believed to 表人们的信念，不是作者证明超自然事件；are placed 描述可观察的仪式动作。两种被动承担不同的信息功能。完成学习后，请介绍一个真实或虚构纪念习俗，标明来源，分别写行动、意义和收尾安排。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>lantern</td><td>/ˈlæntən/</td><td>n.</td><td>灯笼</td><td>a paper lantern</td></tr><tr><td>festival</td><td>/ˈfestɪvəl/</td><td>n.</td><td>节庆</td><td>a local festival</td></tr><tr><td>ancestor</td><td>/ˈænsestə/</td><td>n.</td><td>祖先</td><td>honour an ancestor</td></tr><tr><td>tradition</td><td>/trəˈdɪʃən/</td><td>n.</td><td>传统</td><td>a family tradition</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>honour the memory of — 纪念某人</li><li>according to tradition — 按照传统，标明文化来源</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：are believed to 表人们的信念，不是作者证明超自然事件；are placed 描述可观察的仪式动作。两种被动承担不同的信息功能。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The lanterns are placed by the river to honour family ancestors.</p></blockquote><p>人们把灯笼摆在河边，以纪念家族祖先。</p><p>are placed 是一般现在时被动，概括仪式做法；by the river 是地点而非执行者，to honour 表目的。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>by 不总是被动执行者：by the river 表在河边，不是河流摆放灯笼。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 to honour 前轻停，重读 ancestors；区分 tradition 的 /ʃ/ 与 lanterns 的词尾 /z/。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The lanterns are placed by the river to honour family ancestors. In this fictional village, families tell stories about older generations. They collect the lanterns afterwards to keep the river clean.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>介绍一个真实或虚构纪念习俗，标明来源，分别写行动、意义和收尾安排。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：are placed 是一般现在时被动，概括仪式做法；by the river 是地点而非执行者，to honour 表目的。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：by 不总是被动执行者：by the river 表在河边，不是河流摆放灯笼。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>by the river 在例句中表示执行者还是地点？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 地点。</p><p><strong>解析：</strong> river 不是摆灯动作的执行者，by 在此意为在旁边。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>仪式后人们如何处理灯笼？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They collect them.</p><p><strong>解析：</strong> 原创示范明确收回灯笼，没有描述放任它们进入水中。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“据说这个节日有很长的历史”译成报道被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The festival is said to have a long history.</p><p><strong>解析：</strong> is said to 标示传闻或传统说法，不等于独立核实。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-095">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/review">全册自测</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
